    public static JSONObject summary(JSONObject value)throws Exception {JSONObject out=new JSONObject();for(String key:new String[]{"format","selectionHash","snapshotIdentity","sourceDigest","runtimeId","runtimeIdentity","role","workItemId","scopeEnforced","osSandboxVerified","sameUidExecutionAcknowledged","sourceSecretsAbsenceVerified"})if(value.has(key))out.put(key,value.get(key));return out.put("fileCount",value.getJSONArray("sourceManifest").length()).put("commandTemplates",value.getJSONArray("templates")).put("fullManifestIncluded",false).put("sourceDigestMeaning","fixed_baseline_not_current_checkout_use_project_inspect");}
