    public static final class FreezeCapture {
        private final TeamProjectWorkspaces issuer;private final String nativeBinding;private final JSONObject context,source,actual,checks,texts;
        private FreezeCapture(TeamProjectWorkspaces issuer,JSONObject binding,JSONObject context,JSONObject source,JSONObject actual,JSONObject checks,JSONArray texts)throws Exception{this.issuer=issuer;nativeBinding=TeamWorkFiles.canonical(binding);this.context=new JSONObject(context.toString());this.source=new JSONObject(source.toString());this.actual=new JSONObject(actual.toString());this.checks=new JSONObject(checks.toString());this.texts=new JSONObject().put("files",texts);}
        public boolean belongsTo(TaskStore tasks,JSONObject binding)throws Exception{return issuer.tasks==tasks&&nativeBinding.equals(TeamWorkFiles.canonical(binding));}
        public JSONObject view()throws Exception{return new JSONObject().put("selectionHash",context.getJSONObject("selection").getString("selectionHash")).put("checkoutId",context.getString("checkoutId")).put("sourceDigest",source.getString("sourceDigest")).put("sourceManifest",source.getJSONArray("files")).put("snapshotIdentity",actual.getString("snapshotIdentity")).put("checks",checks);}
        public JSONArray texts()throws Exception{return new JSONArray(texts.getJSONArray("files").toString());}
        public JSONObject evidence()throws Exception{return new JSONObject().put("format","pocketworld.team-project-evidence.v1").put("selectionHash",context.getJSONObject("selection").getString("selectionHash")).put("sourceDigest",source.getString("sourceDigest")).put("manifestHash",TaskStore.capabilityFingerprint(new JSONObject().put("files",source.getJSONArray("files")))).put("snapshotIdentity",actual.getString("snapshotIdentity")).put("checks",checks).put("businessVerified",false).put("osSandboxVerified",false);}
    }
